from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }
    result = []

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * interval)).isoformat()
            for i in range(count)
        ]

    if kind == "WEEKLY":
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        monday = first - timedelta(days=first.weekday())

        while True:
            for weekday in selected:
                candidate = monday + timedelta(days=weekday)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=interval)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        number = int(parts[2])
        weekday = weekdays[parts[3]] if len(parts) == 4 else None

        while True:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, days_in_month = monthrange(year, month)

            if weekday is None:
                day = days_in_month if number == -1 else number
            elif number == -1:
                last_weekday = (first_weekday + days_in_month - 1) % 7
                day = days_in_month - (last_weekday - weekday) % 7
            else:
                day = 1 + (weekday - first_weekday) % 7 + 7 * (number - 1)

            if day <= days_in_month:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += interval

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = first.year

        while True:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            year += interval
